package jp.personal.hanshinedge.validation;
import android.content.*;import android.os.SystemClock;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.junit.Test;import org.junit.runner.RunWith;import org.json.*;import java.io.*;import java.time.*;import jp.personal.hanshinedge.prospective.*;import static org.junit.Assert.*;
/** Actual read-only source probe. After post-time, it must report BLOCKED, never replay success. */
@RunWith(AndroidJUnit4.class)public class LiveProspectiveProbeTest {
 @Test public void observeCurrentAvailabilityWithoutRetroactiveCredit()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();JSONObject report=new JSONObject().put("observed_at",Instant.now().toString()).put("REAL_MONEY","BLOCKED").put("F0_STATUS","NOT_AVAILABLE").put("STAKE_RULE","NOT_AVAILABLE").put("real_timechain_success",0);JSONArray observations=new JSONArray();int registered=0;try(ProspectiveRuntime r=new ProspectiveRuntime(c,"live-readonly-probe")){try{JSONArray catalog=JraSource.today(c);report.put("races",catalog.length());for(int i=0;i<catalog.length();i++){JSONObject item=catalog.getJSONObject(i),race=item.getJSONObject("race"),receipt=item.getJSONObject("receipt");JSONObject reg=r.register(race,receipt,System.currentTimeMillis(),SystemClock.elapsedRealtime());registered+=reg.optBoolean("REAL_PROSPECTIVE")?1:0;observations.put(new JSONObject().put("race_id",ProspectiveRuntime.canonical(race)).put("registration",reg));if(reg.optBoolean("REAL_PROSPECTIVE")){long post=ProspectiveRuntime.stamp(reg.getString("scheduled_post_time")),now=System.currentTimeMillis();for(int k=0;k<4;k++)if(Math.abs(now-(post-ProspectiveRuntime.TARGET[k]*1000L))<=ProspectiveRuntime.TOLERANCE[k]*1000L){JSONObject[] fresh={null};JSONObject current=JraSource.latest(c,reg,fresh);JSONObject capture=r.capture(reg.getString("race_id"),ProspectiveRuntime.STAGE[k],current,fresh[0],System.currentTimeMillis(),SystemClock.elapsedRealtime());if(capture.getJSONObject("snapshot").getString("status").equals("PASS"))report.put("real_timechain_success",report.getInt("real_timechain_success")+1);}}}report.put("source_probe","FETCHED");}catch(Exception e){report.put("source_probe","UNAVAILABLE").put("error",e.toString());}if(observations.length()>0){try{JSONObject deniedOrRegistered=observations.getJSONObject(0).getJSONObject("registration");if(System.currentTimeMillis()>=ProspectiveRuntime.stamp(deniedOrRegistered.getString("scheduled_post_time"))){JSONObject[] proof={null};JSONObject official=JraSource.outcome(c,deniedOrRegistered,proof);report.put("read_only_result_probe",new JSONObject().put("status","PARSED").put("result",official).put("receipt",proof[0]).put("runtime_append",false).put("prospective_credit",0));}}catch(Exception e){report.put("read_only_result_probe",new JSONObject().put("status","UNAVAILABLE").put("error",e.toString()).put("prospective_credit",0));}}assertEquals(0,r.runtime.formalBuyStatus().getInt("count"));report.put("formal_buy_count",0).put("registrations",registered).put("observations",observations).put("gate",report.getInt("real_timechain_success")>0?"REAL_MILESTONE_OBSERVED":"NOT_MET_NO_PRE_RACE_MILESTONE");File dir=new File(c.getFilesDir(),"validation");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"live-prospective-probe.json"))){out.write(report.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}}}
}
